-- ============================================================
-- spell_proc: gating for the three shard-generation talents
-- ============================================================
-- ProcFlags 65536 = PROC_FLAG_DONE_SPELL_MAGIC_DMG_CLASS_NEG
-- ProcFlags 262144 = PROC_FLAG_DONE_PERIODIC
-- SpellTypeMask 1 = PROC_SPELL_TYPE_DAMAGE
-- SpellPhaseMask 2 = PROC_SPELL_PHASE_HIT  (MUST be non-zero)
-- HitMask 2 = PROC_HIT_CRITICAL
-- SchoolMask 4 = SPELL_SCHOOL_MASK_FIRE
-- NOTE: DELETE matches on ABS(SpellId).  A NEGATIVE spell_proc id means
-- "apply to the whole rank chain", and such a row is loaded first and
-- propagates to every rank -- any positive per-rank row for a later rank is
-- then rejected as a "duplicate entry" and silently discarded
-- (SpellMgr.cpp:2071).  The core ships negative rows for several of these
-- talents, so deleting only the positive ids would leave the core row in
-- charge with ProcFlags = 0 and the proc would never fire.
DELETE FROM `spell_proc` WHERE ABS(`SpellId`) IN (18135, 18136, 18119, 18120, 18126, 18127);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
-- Burning Soul: fire spell crits, 15% / 30%
(18135, 4, 5, 0, 0, 0, 65536, 1, 2, 2, 0, 0, 0, 15, 0, 0),
(18136, 4, 5, 0, 0, 0, 65536, 1, 2, 2, 0, 0, 0, 30, 0, 0),
-- Aftermath: Immolate (family mask 0x4) periodic damage. Chance 100 here;
-- the real gate is the crit-chance roll in spell_warl_shard_on_proc.
(18119, 0, 5, 4, 0, 0, 262144, 1, 2, 0, 0, 0, 0, 100, 0, 0),
(18120, 0, 5, 4, 0, 0, 262144, 1, 2, 0, 0, 0, 0, 100, 0, 0),
-- Molten Rain: Rain of Fire (family mask 0x20). Cooldown 0 so it can fire
-- once per enemy per tick -- that is the "from each enemy hit" clause.
(18126, 0, 5, 32, 0, 0, 65536, 1, 2, 0, 0, 0, 0, 8, 0, 0),
(18127, 0, 5, 32, 0, 0, 65536, 1, 2, 0, 0, 0, 0, 15, 0, 0);

-- ============================================================
-- spell_script_names: one shared AuraScript for all three talents
-- ============================================================
-- Negative IDs apply the script to every rank of the spell chain.
DELETE FROM `spell_script_names` WHERE `ScriptName` = 'spell_warl_shard_on_proc';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(-18135, 'spell_warl_shard_on_proc'),
(-18119, 'spell_warl_shard_on_proc'),
(-18126, 'spell_warl_shard_on_proc');
